package com.turboio.addon;

import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;

/** Actual capture runtime/worker -> upload catalog bridge. Native IO is fake. */
public final class LifelogAudioUploadCatalogTest {
 static int checks;static final String A=String.join("",Collections.nCopies(64,"a"));static LifelogAudioRuntime active;
 static void yes(boolean v){checks++;if(!v)throw new AssertionError("upload catalog "+checks);}static Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 static void singleton(LifelogAudioRuntime value)throws Exception{Field f=LifelogAudioRuntime.class.getDeclaredField("instance");f.setAccessible(true);f.set(null,value);}
 static LifelogAudioRuntime boot(File files)throws Exception{Host107Login.active=new OfficialAccountBinding(A);Host107Login.delayMs=Host107Login.readCostMs=0;android.os.Handler.enabled=true;android.os.Handler.hold=false;android.os.SystemClock.now=100000;singleton(null);LifelogAudioRuntime.boot(new android.content.Context(files));Field f=LifelogAudioRuntime.class.getDeclaredField("instance");f.setAccessible(true);return (LifelogAudioRuntime)f.get(null);}
 static void awaitSaved(long count)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<until){Object c=field(active,"collector");if(c!=null&&((Number)((LifelogAudioCollector)c).snapshot().get("saved_batches")).longValue()>=count)return;Thread.sleep(5);}throw new AssertionError("capture queue did not save");}
 static byte[] wire(int marker)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{8,1,16,(byte)0xa3,1});byte[] message=WireJson.bytes(WireJson.object("taskId","task-one"));out.write(26);out.write(message.length);out.write(message);out.write(new byte[]{34,(byte)0xf0,1});for(int i=0;i<240;i++)out.write(marker);return out.toByteArray();}
 static String hash(File files,Object row)throws Exception{Map<String,Object> archive=WireJson.map(row);return TaskWire.hash(Files.readAllBytes(new File(files,"lifelog-audio/"+A+"/"+archive.get("stream")+"/original.frames").toPath()));}
 static void close()throws Exception{if(active==null)return;try{Object collector=field(active,"collector");if(collector!=null)((LifelogAudioCollector)collector).stop("capture_stopped").get(6,TimeUnit.SECONDS);Object library=field(active,"library");if(library!=null)((LifelogAudioLibrary)library).close();}finally{for(String name:new String[]{"io","contextIO"}){ScheduledExecutorService io=(ScheduledExecutorService)field(active,name);io.shutdownNow();yes(io.awaitTermination(3,TimeUnit.SECONDS));}active=null;singleton(null);}}
 static void rejected(CompletableFuture<?> future,String code)throws Exception{try{future.get(6,TimeUnit.SECONDS);throw new AssertionError("catalog accepted");}catch(ExecutionException e){yes(code.equals(e.getCause().getMessage()));}}
 public static void main(String[] args)throws Exception{File files=new File(args[0]);yes(files.mkdir());try{
  singleton(null);rejected(LifelogAudioRuntime.catalogForUpload(A),"AUDIO_CAPTURE_NOT_READY");active=boot(files);long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(field(active,"token")==null&&System.nanoTime()<until)Thread.sleep(5);yes(field(active,"token")!=null);
  LifelogAudioRuntime.incoming("peer-test",wire(1));awaitSaved(1);OfficialLifelogSnapshot.Source source=new OfficialLifelogSnapshot.Source();source.sourceType="conversation";source.sourceId="task-one";LifelogAudioRuntime.sources(A,Arrays.asList(source));
  AudioSyncSession.Catalog before=LifelogAudioRuntime.catalogForUpload(A).get(6,TimeUnit.SECONDS);yes(before.account.equals(A)&&before.sessions.size()==1&&before.archives.size()==1);yes(Boolean.TRUE.equals(WireJson.map(before.sessions.get(0)).get("source_link_verified")));yes("open".equals(WireJson.map(before.archives.get(0)).get("phase")));String initial=hash(files,before.archives.get(0));
  for(int i=0;i<8;i++){AudioSyncSession.Catalog repeat=LifelogAudioRuntime.catalogForUpload(A).get(6,TimeUnit.SECONDS);yes(repeat.archives.size()==1&&"open".equals(WireJson.map(repeat.archives.get(0)).get("phase")));yes(initial.equals(hash(files,repeat.archives.get(0))));}
  CompletableFuture<List<Object>> frozen=new CompletableFuture<>();LifelogAudioRuntime.freeze(A,LifelogAudioLibrary.material(A,"task-one"),(sessions,rows,error)->{if(error.isEmpty())frozen.complete(rows);else frozen.completeExceptionally(new IOException(error));});yes("sealed".equals(WireJson.map(frozen.get(6,TimeUnit.SECONDS).get(0)).get("phase")));
  LifelogAudioRuntime.incoming("peer-test",wire(2));awaitSaved(2);AudioSyncSession.Catalog continued=LifelogAudioRuntime.catalogForUpload(A).get(6,TimeUnit.SECONDS);yes(continued.archives.size()==2&&"sealed".equals(WireJson.map(continued.archives.get(0)).get("phase"))&&"open".equals(WireJson.map(continued.archives.get(1)).get("phase")));yes(initial.equals(hash(files,continued.archives.get(0))));Host107Login.active=new OfficialAccountBinding(String.join("",Collections.nCopies(64,"d")));rejected(LifelogAudioRuntime.catalogForUpload(A),"OFFICIAL_ACCOUNT_CHANGED");Host107Login.active=new OfficialAccountBinding(A);close();
  active=boot(files);AudioSyncSession.Catalog recovered=LifelogAudioRuntime.catalogForUpload(A).get(6,TimeUnit.SECONDS);yes(recovered.archives.size()==2&&recovered.sessions.size()==1);for(Object row:recovered.archives)yes("sealed".equals(WireJson.map(row).get("phase")));yes(Boolean.FALSE.equals(WireJson.map(recovered.sessions.get(0)).get("recording_complete")));yes(initial.equals(hash(files,recovered.archives.get(0))));
  System.out.println("Lifelog audio upload catalog: "+checks+" checks passed; actual runtime IO, read-only polling and historical recovery");
 }finally{close();android.os.Handler.release();}}
}
